package ntnu.bidata.iir.sensornode;

import ntnu.bidata.iir.common.SensorType;

/** Creates sensors from a spec like "temp:1" (type:instance). The known types live in SensorType. */
// Code generated by an AI
public final class SensorFactory {
    private SensorFactory() { }

    public static Sensor create(String spec) {
        SensorType type = SensorType.find(spec)
                .orElseThrow(() -> new IllegalArgumentException("Unknown sensor type: " + spec));
        if (type.isLevel()) {
            return new LevelSensor(spec, type.start());
        }
        if (type.isSwitch()) {
            return new SwitchSensor(spec);
        }
        return new RandomWalkSensor(spec, type.start(), type.min(), type.max(), type.step(), type.pull());
    }
}
